/* Intermediate9: delivery permission, retry state and business acknowledgement contracts. */
(function(){
  const N=AG.aws.n,clone=x=>JSON.parse(JSON.stringify(x)),A='123456789012',R='ap-south-1';
  const arn=n=>`arn:aws:sqs:${R}:${A}:${n}`,url=n=>`https://sqs.${R}.amazonaws.com/${A}/${n}`,TOPIC=`arn:aws:sns:${R}:${A}:order-events`;
  const Q=(q,correct,wrong,answer,explain)=>{const choices=wrong.slice();choices.splice(answer,0,correct);return {q,choices,answer,explain};};
  const table=(heads,rows)=>'<div class="tbl-wrap"><table><tr>'+heads.map(h=>'<th>'+h+'</th>').join('')+'</tr>'+rows.map(row=>'<tr>'+row.map(v=>'<td>'+v+'</td>').join('')+'</tr>').join('')+'</table></div><p class="muted">Phone par table sideways swipe karo.</p>';
  const EVENT={type:'OrderPlaced',eventId:'evt-101',orderId:'order-101',total:499};
  const policy=n=>({Version:'2012-10-17',Statement:[{Effect:'Allow',Principal:{Service:'sns.amazonaws.com'},Action:'sqs:SendMessage',Resource:arn(n),Condition:{ArnEquals:{'aws:SourceArn':TOPIC}}}]});
  const REDRIVE=JSON.stringify({deadLetterTargetArn:arn('orders-dlq'),maxReceiveCount:'3'});
  const SETTINGS={VisibilityTimeout:'120',ReceiveMessageWaitTimeSeconds:'20',RedrivePolicy:REDRIVE};
  const SUB={RawMessageDelivery:'true',FilterPolicyScope:'MessageBody',FilterPolicy:JSON.stringify({type:['OrderPlaced']})};
  const FILES={
    'queue-attributes.json':{desc:'Standard source:120 s visibility,20 s long poll,3 receives to orders-dlq',content:JSON.stringify(SETTINGS,null,2)},
    'subscription.json':{desc:'Raw OrderPlaced body filter; scope is explicitly MessageBody',content:JSON.stringify(SUB,null,2)},
    'order.json':{desc:'Stable business event ID; duplicate deliveries keep the same ID',content:JSON.stringify(EVENT,null,2)},
    ...Object.fromEntries(['email-queue','invoice-queue'].map(n=>[n+'-policy.json',{desc:'Attribute string map with least-privilege SNS SourceArn policy',content:JSON.stringify({Policy:JSON.stringify(policy(n))},null,2)}]))
  };
  const SOLUTION=[
    `aws sqs create-queue --queue-name orders-dlq --attributes '{"MessageRetentionPeriod":"604800"}'`,
    'aws sqs create-queue --queue-name email-queue --attributes file://queue-attributes.json',
    'aws sqs create-queue --queue-name invoice-queue --attributes file://queue-attributes.json',
    'aws sns create-topic --name order-events',
    `aws sqs set-queue-attributes --queue-url ${url('email-queue')} --attributes file://email-queue-policy.json`,
    `aws sqs set-queue-attributes --queue-url ${url('invoice-queue')} --attributes file://invoice-queue-policy.json`,
    ...['email-queue','invoice-queue'].map(n=>`aws sns subscribe --topic-arn ${TOPIC} --protocol sqs --notification-endpoint ${arn(n)} --attributes file://subscription.json`),
    `aws sns publish --topic-arn ${TOPIC} --message file://order.json`,
    ...['email-queue','invoice-queue'].map(n=>`aws sqs receive-message --queue-url ${url(n)} --max-number-of-messages 1 --wait-time-seconds 20 --message-system-attribute-names All`)
  ];
  const queue=(s,n)=>(s.account.queues||[]).find(q=>q.name===n),topic=s=>(s.account.topics||[]).find(t=>t.arn===TOPIC);
  function scoped(q){const rows=q?.policy?.Statement;return Array.isArray(rows)&&rows.length===1&&rows[0].Effect==='Allow'&&rows[0].Principal?.Service==='sns.amazonaws.com'&&rows[0].Action==='sqs:SendMessage'&&rows[0].Resource===q.arn&&(rows[0].Condition?.ArnEquals?.['aws:SourceArn']===TOPIC||rows[0].Condition?.StringEquals?.['aws:SourceArn']===TOPIC);}
  function configured(s){const qs=s.account.queues||[],dlq=queue(s,'orders-dlq'),t=topic(s);return qs.length===3&&s.account.topics.length===1&&dlq?.attributes?.MessageRetentionPeriod==='604800'&&!dlq.isFifo&&!!t&&t.attributes?.FifoTopic!=='true'&&['email-queue','invoice-queue'].every(n=>{const q=queue(s,n);let r;try{r=JSON.parse(q?.attributes?.RedrivePolicy||'{}');}catch(e){return false;}return !!q&&!q.isFifo&&q.visibilityTimeout===120&&q.attributes.ReceiveMessageWaitTimeSeconds==='20'&&r.deadLetterTargetArn===dlq.arn&&Number(r.maxReceiveCount)===3&&q.attributes.MessageRetentionPeriod==='345600';});}
  const bodyMatches=raw=>{try{const value=JSON.parse(raw);return value&&Object.keys(value).length===Object.keys(EVENT).length&&Object.entries(EVENT).every(([k,v])=>value[k]===v);}catch(e){return false;}};
  function subscriptions(s){const t=topic(s);return !!t&&t.subscriptions.length===2&&['email-queue','invoice-queue'].every(n=>t.subscriptions.some(sub=>sub.protocol==='sqs'&&sub.endpoint===arn(n)&&sub.confirmed&&sub.attributes?.RawMessageDelivery==='true'&&sub.attributes.FilterPolicyScope==='MessageBody'&&(()=>{try{const f=JSON.parse(sub.attributes.FilterPolicy);return Object.keys(f).length===1&&Array.isArray(f.type)&&f.type.length===1&&f.type[0]==='OrderPlaced';}catch(e){return false;}})()));}
  function proof(s,n){const q=queue(s,n),t=topic(s),r=q&&(s.account.messagingReads||[]).find(r=>r.queueId===q.queueId&&r.revision===q.revision);if(!q||!t||!r)return false;return r.messages.some(row=>{const m=q.messages.find(m=>m.messageId===row.MessageId&&m.receiptHandle===row.ReceiptHandle&&m.body===row.Body);return !!m&&m.visibleAt>Date.parse(s.account.now||'2026-10-26T00:00:00Z')+(s.account.messagingClock||0)*1000&&bodyMatches(m.body)&&m.provenance?.topicId===t.topicId&&(s.account.snsDeliveries||[]).some(d=>d.status==='delivered'&&d.publicationId===m.provenance.publicationId&&d.queueId===q.queueId&&d.messageId===m.messageId);});}
  const TASKS=[{text:'Exactly2 Standard source queues:120 s visibility,20 s polling,3-receive redrive to7-day DLQ',check:configured},{text:'Each queue allows only SNS order-events via exact queue Resource and SourceArn',check:s=>['email-queue','invoice-queue'].every(n=>scoped(queue(s,n)))},{text:'Two confirmed raw MessageBody OrderPlaced subscriptions',check:subscriptions},{text:'Actual SNS-origin event received with current valid receipt in email queue',check:s=>proof(s,'email-queue')},{text:'Actual SNS-origin event received with current valid receipt in invoice queue',check:s=>proof(s,'invoice-queue')}];
  function plan(k){const poison=k.poison/100,transient=.01,attempts=(1-poison-transient)+transient*Math.min(3,k.retries)+poison*k.retries,capacity=k.workers/(k.seconds+.2)*.8,throughput=capacity/attempts,spare=throughput-k.rate,drain=spare>0?1000/spare:Infinity,overlap=k.visibility<k.seconds+1,window=k.retries*k.visibility,early=k.retries<3?k.rate*3600*transient:0;const ok=k.rate>=20&&k.seconds>=2&&k.poison>=3&&k.workers<=90&&spare>0&&drain<=180&&!overlap&&k.retries>=3&&window<=30;return {attempts,throughput,drain,window,overlap,early,dlq:k.rate*3600*poison,backlog:Math.max(0,1000-spare*3600),ok};}
  const iSeed=()=>({region:R,now:'2026-10-26T00:00:00Z',queues:[{name:'orders-dlq',url:url('orders-dlq'),arn:arn('orders-dlq'),queueId:'original-dlq',isFifo:false,visibilityTimeout:30,attributes:{MessageRetentionPeriod:'604800'},messages:[]},{name:'invoice-queue',url:url('invoice-queue'),arn:arn('invoice-queue'),queueId:'original-invoice',isFifo:false,visibilityTimeout:1,attributes:{VisibilityTimeout:'1'},messages:[{messageId:'original-poison',body:'{"type":"OrderPlaced","eventId":"broken-1","orderId":null}',receiveCount:0},{messageId:'original-good',body:JSON.stringify(EVENT),receiveCount:0}]}],topics:[]});
  const iSolution=[`aws sqs set-queue-attributes --queue-url ${url('invoice-queue')} --attributes file://queue-attributes.json`,...Array(3).fill(`aws sqs receive-message --queue-url ${url('invoice-queue')} --max-number-of-messages 1 --visibility-timeout 0 --message-system-attribute-names All`),`aws sqs receive-message --queue-url ${url('invoice-queue')} --max-number-of-messages 1 --message-system-attribute-names All`,`aws sqs receive-message --queue-url ${url('orders-dlq')} --max-number-of-messages 1 --message-system-attribute-names All`];
  const iTasks=[{text:'Original source/DLQ retained; visibility120 s,redrive3; good event remains intact',check:s=>{const q=queue(s,'invoice-queue'),d=queue(s,'orders-dlq');return s.account.queues.length===2&&q?.queueId==='original-invoice'&&d?.queueId==='original-dlq'&&q.visibilityTimeout===120&&(()=>{try{const r=JSON.parse(q.attributes.RedrivePolicy);return r.deadLetterTargetArn===arn('orders-dlq')&&Number(r.maxReceiveCount)===3;}catch(e){return false;}})()&&q.attributes.ReceiveMessageWaitTimeSeconds==='20'&&q.messages.some(m=>m.messageId==='original-good'&&m.body===JSON.stringify(EVENT));}},{text:'Original poison actually moved to original DLQ after3 source receives',check:s=>{const q=queue(s,'invoice-queue'),d=queue(s,'orders-dlq'),m=d?.messages.find(m=>m.messageId==='original-poison');return !!q&&!!m&&!q.messages.some(m=>m.messageId==='original-poison')&&m.body===iSeed().queues[1].messages[0].body&&m.deadLetterSourceId==='original-invoice'&&m.receiveCount===4;}},{text:'Actual good source event observed; final DLQ receive returns original poison body/current receipt',check:s=>{const q=queue(s,'invoice-queue'),d=queue(s,'orders-dlq'),reads=s.account.messagingReads||[],good=q?.messages.find(m=>m.messageId==='original-good'),poison=d?.messages.find(m=>m.messageId==='original-poison');const time=Date.parse(s.account.now)+(s.account.messagingClock||0)*1000;return !!good&&!!poison&&good.visibleAt>time&&poison.visibleAt>time&&reads.some(r=>r.queueId===q.queueId&&r.revision===q.revision&&r.messages.some(m=>m.MessageId===good.messageId&&m.ReceiptHandle===good.receiptHandle))&&reads.some(r=>r.queueId===d.queueId&&r.revision===d.revision&&r.messages.some(m=>m.MessageId===poison.messageId&&m.ReceiptHandle===poison.receiptHandle&&m.Body===poison.body));}}];
  AG.registerLevels('intermediate',[{
    id:'sqssns',icon:'📨',title:'SQS / SNS — queue, fan-out aur retries',badge:'Message Maestro',
    objectives:['Async acceptance versus completed business work define karo','Visibility/receipt/DLQ state se retry debug karo','Scoped SNS→SQS policy aur body filter build karo','FIFO order/dedup ko business idempotency se separate rakho'],
    hook:{when:'ShopKaro goes national · team 8 · fictional course scenario',title:'Email provider slow; checkout kyun wait kare?',text:'Priya ka order valid hai, lekin email provider 5 seconds leta hai. Ravi SNS→SQS add karta hai. Duplicate email aa jaati hai; invoice queue mein ek bad event repeat hota hai. Neha: order accepted, invoice ready aur email sent ka proof alag-alag dikhao.'},
    steps:[
      {q:'Sync se async kab move karein; customer ko kya promise milega?',analogy:'Dhaba counter token deta hai; token ka matlab order accepted. Token ka matlab khana already plate mein ready nahi. Kitchen queue aur serving status alag hain.',body:'<p>Checkout required payment/stock contract define kare. Email/PDF work normally accepted event ke baad independently retry ho sakta hai. Critical workflows bhi asynchronous ho sakte hain when pending UX, reservation/timeout, reconciliation and compensation are designed. Sync/async choice critical/noncritical label alone se mat karo.</p>',points:['Order commit aur event publish ke beech crash event lose kar sakta hai. Same DB transaction mein outbox record persist karo; dispatcher retries publication with stable eventId. Publication at-least-once ho sakti hai.','One SQS queue shares jobs among competing workers; email aur invoice services need their own copies, so separate queues behind SNS. Standard delivery can repeat and order can change.','Hands-on: dry run mein acceptance, queue delivery, durable intent aur external email ka status separately track karo. Success response ko final business proof mat samjho.'],example:'ShopKaro target: checkout acknowledges accepted order without waiting5 s for email; an accepted order still needs a durable, monitored fulfilment path.',asli:'API contract, data atomicity aur failure recovery pehle. Queue add karna end-to-end reliability ka complete design nahi.'},
      {q:'SQS receive message delete kyun nahi karta?',analogy:'Godown picker parcel ka token temporarily reserve karta hai. Picker crash kare toh reservation expire hoti hai; doosra picker kaam le sakta hai. Receipt har reservation par naya hota hai.',body:'<p>ReceiveMessage → validate/process/durable intent → DeleteMessage with latest ReceiptHandle. Visibility timeout message ko temporarily unavailable karta hai, completion prove nahi karta. Default30 seconds; configure sufficient processing+ack margin. Long tasks can extend visibility with ChangeMessageVisibility, within12 hours from initial receive.</p>',points:['Long polling WaitTimeSeconds1..20 reduces empty receives; zero means short polling. HTTP client timeout should exceed wait time. Long polling is not a delivery delay or message retention.','Retention default4 days, configurable60 seconds..14 days. Queue/message delay0..900 seconds postpones initial visibility; visibility applies after receipt. Current SQS max payload1 MiB; API batch up to10 messages and1 MiB aggregate.','CLI: get-queue-url --queue-name email-queue returns QueueUrl. Send/receive/delete/set attributes use --queue-url, not invented --queue-name. Receive may return fewer than requested. Simulator does not sample Standard ordering or random duplicates. The local model rejects old/expired receipts explicitly; real AWS can accept an old receipt yet leave the message undeleted. Queue attribute updates are immediate locally; real propagation can take up to60 seconds for most settings and15 minutes for retention.'],code:`aws sqs get-queue-url --queue-name email-queue\naws sqs receive-message --queue-url ${url('email-queue')} --wait-time-seconds 20 --message-system-attribute-names All`,asli:'Visibility prevents overlapping attempts in normal timing; Standard still permits duplicates. Debug body, receive count, receipt age and worker outcome together.'},
      {q:'Poison message ko DLQ kab bhejein; redrive kab safe hai?',analogy:'Unreadable address wala parcel separate inspection shelf par jaata hai. Parcel phenkna aur “backlog solved” bolna repair nahi.',body:'<p>Source queue RedrivePolicy names deadLetterTargetArn and maxReceiveCount. A message repeatedly received without delete can move to the DLQ. DLQ RedriveAllowPolicy controls allowed sources; default allowAll, optional denyAll/byQueue with up to10 source queue ARNs. Keep source/DLQ same Region/account and same queue type in this lab.</p>',points:['Lab worker retries3times deliberately. Production retry budget needs measured transient behavior/backoff; Lambda SQS guidance recommends maxReceiveCount at least5. Low maxReceiveCount can isolate healthy transient jobs too early.','Standard message expiry retains original enqueue age after DLQ move; FIFO resets enqueue timestamp. Set DLQ retention longer than source. ApproximateAgeOfOldestMessage on DLQ has its own age meaning, so inspect timestamps and service metrics.','Alarm on nonempty DLQ, oldest age, processing errors and queue backlog. Inspect actual failed body, repair producer/consumer, canary redrive with a rate limit. FIFO DLQ extraction can break required business ordering; quarantine/manual sequence repair may be needed.'],code:'{"RedrivePolicy":"{\\"deadLetterTargetArn\\":\\"'+arn('orders-dlq')+'\\",\\"maxReceiveCount\\":\\"3\\"}"}',asli:'Empty queue is not a success criterion. Preserve original jobs; prove good work progresses and the actual poison body is isolated.'},
      {q:'FIFO ordering aur5-minute dedup kya guarantee karte hain?',analogy:'Bank account ki passbook entries account-wise line mein hain. Har account ek group hai; saare accounts ko ek single line dena throughput bottleneck ban sakta hai.',body:'<p>FIFO requires .fifo name plus FifoQueue=true. MessageGroupId defines ordering scope. Explicit MessageDeduplicationId, or content-based SHA-256 of body only, suppresses producer duplicate sends within5 minutes, including after message deletion. Attributes are excluded from content-based hash.</p>',points:['A group with an in-flight message blocks later receives from that group until deletion/visibility expiry; other groups can proceed. One receive batch may contain multiple ordered messages from a group; consumer must preserve that order.','Non-high-throughput FIFO partitions support300 transactions/s per API action; batching10 can reach3000 messages/s per partition. High-throughput mode/Region quotas change ceilings; partition distribution, batches, payload and consumer parallelism still matter. No universal300 msg/s rule.','Business side effect before delete can repeat after crash. FIFO dedup does not make payment/email exactly once. Current Standard MessageGroupId supports fair queues without FIFO ordering and adds fair-queue request charges.'],asli:'Kab use: strict order per account/order/entity. Kab nahi: independent jobs with no ordering need. Stable eventId and idempotent business path remain necessary.'},
      {q:'SNS fan-out mein filters, raw body aur FIFO kaise choose karein?',analogy:'School notice board ka same notice email desk aur print desk ko milta hai. Department filter decide karta hai kaunsa notice kis desk par jaayega; envelope format decide karta hai desk payload kaise padhega.',body:'<p>SNS topic pushes independent copies to matching confirmed subscribers. Each consumer queue owns retry/retention/DLQ. FilterPolicy defaults to MessageAttributes; body JSON fields need FilterPolicyScope=MessageBody. Policy keys combine AND, allowed values combine OR. AWS filter propagation can take up to15 minutes; local model applies immediately.</p>',points:['RawMessageDelivery=true sends body directly; default false wraps the message in SNS JSON envelope. Choose the consumer contract explicitly. Raw SQS subscriptions support up to10 message attributes; more cause client-side delivery errors.','SNS FIFO supports SQS FIFO and Standard subscribers. Standard subscribers keep at-least-once/best-effort semantics. Direct customer HTTP/email/SMS/mobile subscribers are not FIFO endpoints; Lambda can consume through SQS. Eligible SNS FIFO topics also offer archive/replay; SNS is not universally “no retention/replay”.','Current SNS default256 KiB can be raised using MaximumMessageSize up to1 MiB for supported SQS/Lambda/Firehose configurations, max100subscriptions for larger payloads. S3 claim-check is suitable for larger files. Body filtering scans are billed; attribute filtering is free.'],code:JSON.stringify(SUB,null,2),asli:'Hands-on: subscription.json selects raw OrderPlaced JSON body. OrderCancelled must not route. A confirmed subscription alone does not grant queue delivery permission.'},
      {q:'Publish MessageId mila; queue khaali kyun?',analogy:'Courier booking receipt dispatch acceptance hai. Locked godown gate par courier ke paas entry permission na ho toh booking receipt delivery proof nahi.',body:'<p>Producer identity needs sns:Publish. Separately, destination queue resource policy must allow SNS sqs:SendMessage on the exact queue, scoped to the expected topic using aws:SourceArn. Extra customer-managed KMS key permissions may also be required. Cross-account design needs both sides reviewed.</p>',points:['Read topic, subscription confirmation/filter/raw settings, queue Policy and delivery metrics/logs. Wrong account/Region/SourceArn, missing subscription permission, KMS denial or filter mismatch can explain an empty queue.','SNS subscription DLQ captures delivery failures; source SQS processing DLQ captures consumer retry exhaustion. Permanent client errors such as policy denial need repair; do not assume all failures retry until delivery.','Galti jo sab karte hain: Principal:* policy, filter scope left at attributes, acknowledging before durable work, deleting queue to clear alarm. Production me kya hota hai: policy/KMS drift or expired retention loses delayed work unless delivery/age alarms and reconciliation exist.'],code:JSON.stringify(policy('email-queue'),null,2),asli:'Main mission requires least-privilege policy and actual SNS-origin body returned from both queues. Direct SQS injection or successful publish history cannot qualify.'},
      {q:'Lambda SQS batch mein ek record fail ho toh kya karein?',analogy:'Ten parcels ke batch mein ek bad address hai. Nine successful parcels ko dobara dispatch karna duplicate effort hai; failed parcel ki ID separately report karo.',body:'<p>Event source mapping polls SQS; Lambda asynchronous invocation destinations do not replace the source queue processing DLQ. Execution role needs queue permissions and applicable KMS decrypt. Visibility must be at least function timeout; AWS recommends6×function timeout plus batching window for retry/throttle room.</p>',points:['ReportBatchItemFailures enables partial batch responses, and handler must return batchItemFailures with failed message IDs. Setting the flag without correct handler output does not isolate failed records.','For FIFO, stop processing after the first failure and include failed plus unprocessed IDs to preserve ordering. Application side effects still need per-event idempotency/atomicity.','Example timeout10 s plus window5 s gives recommended visibility65 s; visibility10 s meets basic validation but has no recommended retry margin. Tune batch size/concurrency from actual downstream limits, queue age, errors and saturation.'],code:'{"batchItemFailures":[{"itemIdentifier":"failed-message-id"}]}',asli:'Function succeeded transport-wise does not prove every item succeeded. Monitor actual failed IDs, durable effects and queue age; previous Lambda lab runtime is separate evidence.'},
      {q:'SQS, SNS, EventBridge, Kinesis ya MQ; cost ka decision kaise?',analogy:'Job tokens, notice copies, routing desk, replayable diary aur legacy telephone exchange alag contracts solve karte hain. Service name se pehle work contract choose karo.',body:table(['Need','Candidate','Boundary'],[['Competing workers + buffer','SQS Standard; FIFO when per-entity order required','Receipt/delete + idempotent processing; consumed/deleted jobs are not an event log'],['Independent durable copies','SNS→one SQS per consumer','Queue policy/filter, retry/retention, subscription DLQ'],['AWS/SaaS/content routing + workflow integration','EventBridge','SNS also filters body; compare sources/rules/integrations rather than filtering alone'],['Ordered retained records + independent offsets/replay','Kinesis Data Streams','Per-shard order, partition skew, retention and consumer cost'],['Existing JMS/AMQP broker clients','Amazon MQ','Engine-specific protocols/HA; broker capacity and maintenance remain']]),points:['Approx us-east-1 gross list prices: Standard SQS$0.40/million requests; FIFO$0.50/million eligible message actions; Standard fair queues add$0.10/million affected requests. Standard SNS$0.50/million paid API requests. Each64 KiB payload chunk is a request unit; batches/empty polls/retries change counts.','Example30million small publishes/month,2queues,one send+receive+delete per queue/event: SNS approx$15 plus SQS approx$72 = $87 ≈₹7656 at₹88/$1, before free allowances/credits. This is request-only illustration, not the entire bill: body-filter scans, transfer, KMS, workers, retries, empty polls, tax and larger payloads are excluded.','SNS→SQS has no per-message SNS delivery fee, but SNS data transfer can still be charged. Distinguish free allowance from a blanket free lab promise. Production needs outbox retention/dispatch monitoring and external-provider reconciliation, not only broker health.'],asli:'Decision: one job→SQS; independent copies→SNS+SQS; richer event integrations→EventBridge; retained streaming replay→Kinesis; legacy broker API→MQ. Measure failure semantics and full cost.'}
    ],
    myth:[{myth:'FIFO means an email/payment can happen only once',sach:'Producer dedup window and per-group ordering do not atomically include external effects. Stable IDs, durable intents and provider reconciliation/idempotency still matter.'},{myth:'Publish MessageId proves every consumer received the event',sach:'SNS acceptance, subscription filtering, queue policy/KMS delivery and consumer business acknowledgement are separate states.'},{myth:'One SQS queue fans every event to email and invoice workers',sach:'Workers compete for jobs in one queue. Independent services need independent durable copies, commonly SNS→separate SQS queues.'},{myth:'Queue depth zero proves retries fixed',sach:'Purge/delete/expiration can erase work. Preserve source jobs, verify actual business outcomes and inspect the real poison body/DLQ.'}],
    playbook:{title:'Kab queue, kab fan-out, kab event log?',use:['SQS for background work and bounded load buffer; one queue per distinct consumer service','FIFO for strict order within a chosen entity group; idempotency for every repeated business event'],avoid:['Claiming completed payment/email from accepted broker message','One global FIFO group or unlimited retries without measured need','Purge/delete as a debugging fix or public wildcard queue policy'],how:['Define accepted/completed states and DB+event atomicity','Choose worker sharing versus independent copies versus retained replay','Configure SourceArn policy, filter scope/raw contract, visibility, retention, processing/subscription DLQs','Observe actual body/receipt, durable intent, retry counts and oldest age; canary recovery'],redflags:['Same eventId with different payload','Age grows while worker CPU low; KMS/policy/poison errors','FIFO groups collapse into one hot key; healthy messages redrive too early'],rule:'Service choice follows delivery/order/replay contract. End-to-end business completion needs its own proof.'},
    exam:[{cue:'Decouple producers and scale competing workers',pick:'SQS',why:'Queue buffers work; consume/delete and retry semantics matter.'},{cue:'Same event to multiple independent services',pick:'SNS→separate SQS queues',why:'Durable copies per consumer, with scoped queue policies.'},{cue:'Order per customer/account',pick:'FIFO + MessageGroupId',why:'Per-group order; five-minute dedup is not atomic external work.'},{cue:'Poison keeps reappearing',pick:'Source RedrivePolicy + processing DLQ',why:'Receive budget isolates failures; inspect/repair before redrive.'},{cue:'Publish succeeds, queue empty',pick:'Check subscription/filter, SQS Policy and KMS',why:'Acceptance differs from delivery; expected SourceArn matters.'},{cue:'Reduce empty ReceiveMessage calls',pick:'Long polling up to20 seconds',why:'Reduces empty polls, not delivery latency by queue delay.'},{cue:'Defer initial processing10 minutes',pick:'DelaySeconds600',why:'Initial delay differs from visibility after receipt; max15 minutes.'},{cue:'Large files through messaging',pick:'S3 claim-check or eligible configured larger message',why:'Current SQS1 MiB; SNS default256 KiB/configurable1 MiB with restrictions.'},{cue:'Partial Lambda batch failure',pick:'ReportBatchItemFailures + failed IDs',why:'Handler contract and FIFO ordering rules still apply.'}],
    stages:[
      {type:'dryrun',title:'🔬 Accepted → delivered → durable work',goal:'Har click par broker state aur business state dekho; three decisions choose karo.',nodes:[N('app',100,250,{label:'Order API'}),N('sns',400,250,{label:'Topic'}),N('sqs#mail',650,110,{label:'Email'}),N('sqs#invoice',650,390,{label:'Invoice'}),N('lambda',900,110,{label:'Worker'}),N('sqs#dead',900,390,{label:'DLQ'})],edges:[{from:'app',to:'sns'},{from:'sns',to:'sqs#mail'},{from:'sns',to:'sqs#invoice'},{from:'sqs#mail',to:'lambda'},{from:'sqs#invoice',to:'sqs#dead'}],panels:[{id:'broker',title:'Broker delivery'},{id:'business',title:'Business outcome'}],steps:[
        {say:'Order DB commit aur outbox intent durable hain. Dispatcher publishes stable eventId evt-101.',clock:'t=0 s',flows:[{from:'app',to:'sns',label:'event'}],panels:{broker:['SNS accepted publication','Queue delivery not yet proved'],business:['Order accepted','Email not sent']}},
        {say:'Invoice queue policy lacks SourceArn Allow. SNS accepted publish, but invoice delivery is denied.',flows:[{from:'sns',to:'sqs#invoice',label:'denied',tone:'bad'}],ask:Q('Queue empty despite Publish MessageId: next debugging action?', 'Inspect subscription/filter, destination queue policy and applicable KMS permissions',['Increase the email worker timeout before inspecting the queue delivery permission','Delete the invoice queue and treat missing messages as completed invoice work','Switch every producer to FIFO and assume policy failures become successful deliveries'],0,'Acceptance is not delivery. Inspect permission/filter/KMS; worker timeout does not grant SendMessage, deletion loses work, and FIFO does not bypass authorization.')},
        {say:'Ravi repairs exact SNS SourceArn permission. Dispatcher republishes durable outbox event; raw OrderPlaced reaches both queues.',flows:[{from:'sns',to:'sqs#mail',label:'copy',tone:'ok'},{from:'sns',to:'sqs#invoice',label:'copy',tone:'ok'}],panels:{broker:['Two independent queue copies','Matching body filter; scoped permission'],business:['No external email yet']}},
        {say:'Email worker sends email, then crashes before DeleteMessage. Visibility120 seconds expires; the event can be received again.',clock:'t=120 s',flows:[{from:'sqs#mail',to:'lambda',label:'try',tone:'slow'}],ask:Q('Repeated eventId arrives after an ambiguous email outcome. Safe design?', 'Use a durable intent and provider idempotency/reconciliation; ack only the agreed durable contract',['Trust FIFO five-minute dedup to atomically include every external email-provider side effect','Delete the repeated event immediately without checking any previous durable or external outcome','Write a dedup flag first, then send later with no dispatcher or recovery of pending work'],1,'Durable intent plus idempotent/reconciled dispatch handles the external boundary. FIFO does not include email atomicity; blind delete can lose work; a standalone early flag can skip an email after a crash.')},
        {say:'Invoice consumer cannot validate broken event orderId=null. Three receives fail without delete; the next attempt isolates the actual body in DLQ.',flows:[{from:'sqs#invoice',to:'sqs#dead',label:'DLQ',tone:'bad'}],panels:{broker:['Source retry budget exhausted','Poison body preserved in DLQ'],business:['Good jobs can progress','Poison invoice still unresolved']},ask:Q('DLQ contains the original malformed event. Recovery order?', 'Inspect and repair the cause, canary redrive at a bounded rate, verify business effects',['Purge both queues first so alarms clear before anyone inspects the original failed payload','Set unlimited receive retries and assume corrupt fields become valid after enough deliveries','Delete the good jobs too so the same queue metrics appear consistent across all consumers'],2,'Inspect actual payload/cause, repair and controlled replay. Purge loses evidence/work; retries cannot repair deterministic corruption; removing good jobs hides failure.')},
        {say:'Lab stores one pending-dispatch intent per consumer#eventId. Duplicate input verifies the existing matching intent; no external email is claimed.',panels:{broker:['Receipts acknowledged only after durable intent','SNS delivery DLQ differs from source processing DLQ'],business:['Email intent1; invoice intent1','External sends0 in this local lab']}}
      ],lesson:'Accepted event, queue copy, durable consumer intent and external side effect are separate proofs.'},
      {type:'flowlab',title:'🎛️ Retry budget aur worker capacity',goal:'Retain at least 20 msg/s, 2 s work and 3% poison. Use at most 90 worker slots. Drain the initial 1000-job burst within 180 s. Avoid modeled visibility overlaps; allow 3 transient attempts. Poison visibility-window budget must fit 30 s. Try: 20 msg/s, 80 slots, 2 s work, visibility 5 s, retries 3, poison 3%.',scenario:'Teaching model, not an AWS benchmark: 80% utilization allowance; processing + 0.2 s acknowledgement; extra 0.8 s timing margin. 1% jobs fail the first 2 attempts; selected poison% always fail. Expected attempts per original job includes bounded retries. Poison window = maxReceiveCount × visibility is an approximate window budget, not guaranteed DLQ latency. Steady-state DLQ/hour excludes warmup, sampling and stochastic Standard duplicates.',knobs:[{id:'rate',label:'Producer',min:10,max:30,step:10,value:20,unit:'msg/s'},{id:'workers',label:'Concurrent worker slots',min:10,max:100,step:10,value:20,unit:'slots'},{id:'seconds',label:'Processing per attempt',min:1,max:3,step:1,value:2,unit:'s'},{id:'visibility',label:'Visibility timeout',min:1,max:10,step:1,value:1,unit:'s'},{id:'retries',label:'maxReceiveCount',min:1,max:5,step:1,value:1,unit:'receives'},{id:'poison',label:'Permanent poison fraction',min:0,max:6,step:3,value:3,unit:'%'}].map(knob=>({...knob,fmt:v=>v+(knob.unit==='%'?'':' ')+knob.unit})),model:k=>{const p=plan(k);return {readouts:[{label:'Original-job capacity',value:p.throughput.toFixed(1)+' msg/s',tone:p.throughput>k.rate?'ok':'bad'},{label:'Expected attempts / original job',value:p.attempts.toFixed(2)},{label:'Initial1000-job burst drain',value:Number.isFinite(p.drain)?Math.ceil(p.drain)+' s':'growing backlog',tone:p.drain<=180?'ok':'bad'},{label:'Backlog after1 hour',value:Math.round(p.backlog)+' jobs'},{label:'Modeled visibility overlap risk',value:p.overlap?'Yes: timeout below work+margin':'No modeled overlap',tone:p.overlap?'bad':'ok'},{label:'Steady poison DLQ / hour',value:Math.round(p.dlq)+' jobs'},{label:'Healthy transient jobs isolated too early / hour',value:Math.round(p.early)+' jobs',tone:p.early?'bad':'ok'},{label:'Poison visibility-window budget',value:p.window+' s',tone:p.window<=30?'ok':'bad'}],verdict:{ok:p.ok,text:p.ok?'Fixed workload preserved, bounded worker budget, stable backlog and retry window fit. Real timing/duplicates still require measurement.':'Capacity, workload, worker budget, visibility margin and retry window must all fit; reducing test demand or deleting jobs is not a repair.'}};},check:k=>plan(k).ok,lesson:'More retry room improves transient recovery but consumes attempts and delays poison isolation. FIFO/visibility cannot promise zero business duplicates.'},
      {type:'bins',title:'🗂️ Work contract se service choose karo',instructions:'One best-fit candidate per explicit requirement; compare delivery contract, not service name.',bins:[{id:'sqs',label:'SQS'},{id:'sns',label:'SNS + SQS'},{id:'events',label:'EventBridge'},{id:'stream',label:'Kinesis'},{id:'mq',label:'Amazon MQ'}],items:[{text:'Independent image jobs shared among workers',bin:'sqs',explain:'Competing workers consume one queue; idempotent processing handles retries.'},{text:'Order event needs separate email and invoice durable copies',bin:'sns',explain:'One subscribed queue per consumer service, with scoped policies.'},{text:'AWS/SaaS events plus rich rule integrations',bin:'events',explain:'Event bus integrations/rules; SNS also has body filters.'},{text:'Retained ordered records; independent consumers replay offsets',bin:'stream',explain:'Kinesis retained stream with partition/shard semantics.'},{text:'Existing ActiveMQ JMS clients migrate with compatible protocol',bin:'mq',explain:'Amazon MQ matches broker-client compatibility; choose supported engine.'}]},
      {type:'order',title:'🔢 Fan-out setup: permission bhi step hai',instructions:'Build order for this lab: destination → retry contract → topic → permission → subscription → publication → proof.',steps:['Create source queues and same-type DLQ','Configure source visibility/retention/redrive policy','Create the SNS topic','Grant SNS SendMessage on each queue scoped to topic SourceArn','Subscribe each queue with explicit raw/filter scope','Publish stable OrderPlaced event','Receive actual bodies and inspect consumer outcomes'].map((text,i)=>({text,explain:['Create destinations before referencing queue ARNs.','Retry contract belongs to source; DLQ preserves exhausted jobs.','Topic ARN identifies allowed publisher service source.','Queue resource policy grants destination delivery permission.','Consumer contract chooses raw format and correct filter scope.','Stable event ID supports replay/idempotency.','Observe actual queue bodies; broker acceptance is separate.'][i]})),explain:'Queue/Topic ARNs must exist before the scoped policy/subscription; Publish acceptance alone is not end-to-end proof.'},
      {type:'triage',title:'🩺 Publish accepted; invoice queue empty',symptom:'Course fixture: OrderPlaced Publish returned MessageId. Email delivered; invoice queue has no matching body. No live AWS capture claimed.',goal:'Run all delivery clues; identify missing destination permission and the correct fix.',commands:[{cmd:`aws sns get-topic-attributes --topic-arn ${TOPIC}`,out:'TopicArn: '+TOPIC+'\nSubscriptionsConfirmed: 2',clue:false,note:'Topic exists; confirmation does not grant queue permission.'},{cmd:`aws sns list-subscriptions-by-topic --topic-arn ${TOPIC}`,out:'invoice-queue: confirmed SQS; raw=true; FilterPolicyScope=MessageBody; type=OrderPlaced',clue:false,note:'Subscription and body filter match this event.'},{cmd:`aws sqs get-queue-attributes --queue-url ${url('invoice-queue')} --attribute-names All`,out:'QueueArn: '+arn('invoice-queue')+'\nVisibilityTimeout: 120\nPolicy: absent',clue:true,note:'SNS has no queue resource-policy Allow; Publish did not prove delivery.'}],questions:[Q('What explains this specific delivery failure?', 'Missing destination SQS resource-policy Allow for the expected SNS topic',['Visibility120 seconds means every new unreceived message is hidden for120 seconds','Confirmed subscription automatically means the consumer successfully sent an invoice','Long polling20 seconds deletes matching events before the first worker sees the body'],0,'Missing SNS SendMessage permission explains this fixture. Visibility starts after receipt, confirmation is not business completion, and long polling waits for work without deleting it.'),Q('Which repair preserves least privilege and debugging evidence?', 'Allow SNS SendMessage on this queue for exact topic SourceArn; verify delivery again',['Allow every principal every SQS action on every queue so future policy failures disappear','Purge email and invoice queues to remove the mismatch between their current message counts','Decrease maxReceiveCount before delivery so SNS treats the missing permission as successful work'],1,'Scope service/action/resource/SourceArn and republish/reconcile the durable event. Public wildcard is excessive; purge loses jobs; receive count governs consumer retries after SQS delivery.')]},
      {type:'terminal',title:'🖥️ Build secure OrderPlaced fan-out',instructions:'Files are prepared; ls/cat inspect exact attribute maps, policies and JSON event. Use actual QueueUrl/ARN and named files. No real AWS calls occur.',goal:'<p><b>1.</b> Create orders-dlq with7-day MessageRetentionPeriod604800; create Standard email-queue and invoice-queue from queue-attributes.json (120 s visibility,20 s polling,3 receives).</p><p><b>2.</b> Create order-events Standard topic. Apply each matching queue-policy file through set-queue-attributes; each file is an attributes string map containing Policy.</p><p><b>3.</b> Subscribe each queue ARN using subscription.json: raw=true, MessageBody filter for OrderPlaced. Publish file://order.json.</p><p><b>4.</b> Receive from both full QueueUrls with max-number-of-messages1 and system attributes All. Expect actual matching body and a fresh ReceiptHandle in each response. Do not delete: no business consumer runs in this mission. Lab17 demonstrates durable intents before ack.</p><p>Only current SNS-origin deliveries qualify. The model omits wire checksums and network scheduling. Optional sleep N advances only the messaging teaching clock instantly; real shell sleep waits.</p>',account:{region:R,now:'2026-10-26T00:00:00Z',queues:[],topics:[]},files:FILES,tasks:TASKS,solution:SOLUTION,hints:['Separate consumer copies need separate queues. Configure retry target, scoped destination permission and matching filter before publishing.',SOLUTION.slice(0,4).join(' phir '),SOLUTION.slice(4,8).join(' phir '),SOLUTION.slice(8).join(' phir ')],success:AG.allOf(TASKS),successText:'Actual SNS-origin OrderPlaced body returned from both configured Standard queues with current receipts; narrow queue permission and independent retry/DLQ contracts verified. No external email/invoice completion is claimed.'},
      {type:'docker',title:'🐳 Lab17 — real fan-out, durable intents, DLQ',project:'17-sqs-sns-fanout-dlq',goal:'Run scoped host/Moto API tests and inspect actual differences from AWS.',why:'Moto delivers without queue policy and loses FIFO dedup after delete. State-based simulator tests the documented contracts; emulator acceptance is not authorization/runtime proof.',steps:[{text:'Source existing env and run the lab script; it owns a new loopback server and closes only that server.',cmd:'source ../env.sh && ../.venv/bin/python -I lab.py',expect:'17 behavior checks;18 including cleanup. Each consumer receives2 copies but creates1durable pending intent. External emails0.'},{text:'Inspect actual poison receive counts/body and FIFO group observations in output.',expect:'Source counts1,2,3; conflicting total0 moves to DLQ without overwriting original499 intent. A2 waits while B1 proceeds.'},{text:'Read README emulator gaps and cleanup ledger.',expect:'Policy probe receivesWithoutQueuePolicy[1,1]; dedupAfterDeleteBroken true. Final queues/topics/tables[] and OWNED MOTO STOPPED / LISTENER CLOSED.'}],observe:Q('What result does lab17 prove?', 'Duplicate input produced one matching durable pending intent per consumer; external sends remain untested',['FIFO and Moto jointly proved every external payment/email executes exactly once across crashes','A Publish MessageId plus empty source queue proved that every invoice was processed correctly','Queue policies were enforced by Moto because both subscriptions returned confirmed ARNs'],2,'Actual DynamoDB conditional intents survive duplicates independently per consumer. No external sends occurred; empty queues and broker IDs cannot prove business effects; Moto policy enforcement demonstrably diverged.')},
      {type:'quiz',title:'🎓 Delivery, ordering aur debugging decisions',questions:[
        Q('Three email workers and two invoice workers share one Standard queue. Both services need every order. Repair?', 'Create one queue per service behind SNS; workers within each service share that service queue',['Increase each ReceiveMessage batch to5 so SQS permanently assigns identical copies to every service','Use one global FIFO MessageGroupId so each worker receives every order in the same total order','Increase visibility to14 days so both services receive each message before any worker can delete it'],3,'Independent service copies need fan-out and separate queues. Batch size does not broadcast; one FIFO group serializes work;14 days is retention maximum, not visibility, and visibility does not broadcast.'),
        Q('FIFO event produced an email; worker crashed before DeleteMessage. What remains necessary?', 'A durable dispatch contract plus provider idempotency or reconciliation for ambiguous external outcomes',['No further design because FIFO five-minute producer dedup includes all email-provider transactions','Deleting the original FIFO queue after every send so the provider cannot see another delivery','Replacing MessageGroupId with a random value on each retry to preserve business event identity'],0,'FIFO producer dedup does not include external email atomicity. Crash before ack can repeat work; deleting queues loses jobs; random groups lose ordering and are not a business identity.'),
        Q('OrderPlaced body is JSON; no message attributes exist. FilterPolicy type=OrderPlaced delivers nothing. Check?', 'Set FilterPolicyScope to MessageBody and allow propagation; verify queue permission as well',['Set RawMessageDelivery tofalse because raw delivery automatically adds the missing type attribute','Use a larger maxReceiveCount because attribute-based filtering happens after consumer processing','Switch the source queue retention to60 seconds so an attribute-only policy reads the message body'],1,'Default scope is attributes; body filtering must be explicit. Raw/envelope format does not create an attribute; receive retry budget and retention do not change filter scope or permissions.'),
        Q('Processing typically takes45 s, visibility30 s; a worker sees repeated jobs. Best first response?', 'Measure processing/ack tail, increase or extend visibility with margin, keep consumer idempotent',['Use long polling20 seconds as a substitute for visibility because both settings hide in-flight jobs','Delete every message immediately on receipt to eliminate repeated delivery even when processing fails','Move all messages to a DLQ before the first attempt so queue depth cannot grow during processing'],2,'Visibility below work/ack time permits overlap. Measure tails and extend carefully; long polling waits for available work, early delete loses failed work, and preemptive DLQ is not processing.'),
        Q('A payload conflict repeats3times; source redrive maxReceiveCount3; DLQ receives original bad body. Next?', 'Inspect/repair the cause, preserve evidence, canary redrive and verify consumer business outcomes',['Purge the DLQ immediately because any isolated message has already completed its business operation','Raise maxReceiveCount indefinitely because the same invalid orderId becomes valid after enough retries','Delete both source and DLQ then recreate names so missing messages count as successful recovery'],3,'DLQ is isolation, not completion. Repair then controlled replay/reconciliation; purge/delete loses events; deterministic corruption does not heal through unlimited retries.'),
        Q('Need per-account ordering plus independent analytics that tolerates best-effort order. Candidate?', 'SNS FIFO to account-processing SQS FIFO and analytics SQS Standard, with each queue permission scoped',['SNS FIFO directly to customer email and HTTP endpoints, because all push protocols preserve FIFO order','SNS Standard to one global SQS FIFO queue, because Standard topics supply every required FIFO sequence','One Standard queue with MessageGroupId, because fair queues convert every tenant into strict FIFO'],0,'Current SNS FIFO supports both queue types; Standard remains best-effort/at-least-once. Customer push endpoints are not FIFO endpoints; Standard topic cannot provide FIFO queue delivery contract; fair Standard groups do not turn into FIFO.'),
        Q('Lambda timeout10 s, batch window5 s. What distinguishes validation from recommended visibility?', 'At least10 s satisfies timeout validation; AWS recommendation is65 s for this configuration',['Visibility must equal5 s because the batching window replaces the function execution deadline','Visibility10 s is the complete AWS recommendation and no throttling retry allowance is needed','Visibility60 s is the exact recommendation because batching window is excluded from the formula'],1,'Minimum is function timeout; recommended6×timeout+window gives65 s.5 s fails basic validation;10 s lacks recommendation margin;60 s omits the configured window.'),
        Q('A30million/month fan-out estimate counted only Publish calls. What should the request model add?', 'Per-queue send/receive/delete and payload units, with polls/retries/batches and other cost meters reviewed',['Only queue storageGB because SQS receive/delete calls are unmetered after an SNS publication','Only the number of consumers because one worker process equals one billable monthly queue request','Nothing else because SNS→SQS has no per-message delivery fee, so all downstream work is free'],2,'SQS requests are independently metered; payload chunks, retries/polls/batches change units. No SNS per-message SQS delivery fee does not remove SQS, transfer, filtering, KMS or worker costs; worker count is not request count.')
      ]}
    ],
    interview:{title:'Interview — delivery proof and poison isolation',instructions:'Four decisions ke baad original invoice source/DLQ ko preserve karke retry repair aur actual poison readback karo.',questions:[
      Q('Why is a dedup key consumer#eventId safer than eventId alone in one shared intent table?', 'Independent email and invoice consumers need separate durable intents for the same business event',['A shared eventId should intentionally suppress invoice whenever email processed the order first','Adding consumer name makes every repeated delivery unique and removes the need to verify payloads','The key prevents all transport duplicates before SNS publishes any message to a subscribed queue'],3,'One business event can need multiple independent effects. Consumer scope prevents one service suppressing another; repeated same consumer/event still collides for verification; a DB key does not suppress transport publication.'),
      Q('Same consumer/eventId already has pending total499 intent; duplicate now says total0. Ack?', 'Reject the conflicting identity, preserve the original intent and inspect/quarantine rather than blindly ack',['Overwrite the original total silently because every repeated eventId must represent a newer correction','Acknowledge immediately because any existing conditional-write failure proves the new payload is safe','Generate a random eventId during retries so the conflicting payload bypasses duplicate checks'],0,'An existing row proves only identity collision; compare full intended operation. Mismatched payload needs explicit conflict handling; silent overwrite, blind ack or random IDs hides corruption/duplicates.'),
      Q('Why can a source processing DLQ remain empty when SNS lacks queue-policy permission?', 'The event never entered the source queue; inspect SNS delivery failure and subscription DLQ configuration',['SQS processing DLQ contains only successfully processed messages and therefore ignores policy errors','Visibility timeout automatically moves every undelivered SNS publish directly into the source processing DLQ','A confirmed subscription guarantees queue policy, so an empty DLQ means every subscriber completed work'],1,'Consumer retry DLQ operates on messages already in SQS. Delivery failures belong to SNS delivery diagnostics/subscription DLQ; confirmation does not imply permission or business completion.'),
      Q('A worker writes a dedup flag then crashes before sending email; retry skips existing flags. Repair design?', 'Persist a recoverable pending intent and dispatch with idempotent provider key or reconciliation',['Increase the FIFO dedup window to14 days so the skipped external email becomes automatically delivered','Delete the skipped source message sooner so the provider can infer the missing email from queue depth','Use MessageGroupId as the only durable flag because FIFO groups store external dispatch completion'],2,'Pending intent must be recoverable and external ambiguity handled. FIFO five-minute dedup is not configurable14 day email recovery; deleting messages cannot dispatch; group order stores no provider outcome.'),
      {terminal:{title:'🖥️ Repair retry contract; isolate actual poison',goal:'<p>invoice-queue has original-poison (orderId=null) followed by original-good; orders-dlq already exists. Preserve both queue identities and original good event.</p><p>Set queue-attributes.json: visibility120 s,poll20 s,redrive3. Receive source3times using max-number-of-messages1 and visibility-timeout0 to deliberately retry the same failed event immediately. Do not acknowledge poison.</p><p>Receive source again using default120 s: expect good event, after poison moves to DLQ. Finally receive orders-dlq and inspect original poison body/count. Keep good event unacked: business work did not run. Zero timeout is a local deliberate-failure exercise, not production advice.</p>',account:iSeed(),files:FILES,tasks:iTasks,solution:iSolution,hints:['Queue depth zero cannot qualify. Preserve original IDs, route actual poison after retry budget, and read both real bodies.',iSolution[0],iSolution.slice(1,4).join(' phir '),iSolution.slice(4).join(' phir ')],success:AG.allOf(iTasks),successText:'Original source/DLQ retained. Original poison reached actual DLQ after3 source attempts and final receive returned the body; good event remains available for durable business processing. No purge/delete or external success claim.'}}
    ]},
    success:['Delivery acceptance aur business completion alag prove kar sakta hoon','Policy/filter/visibility/receipt/DLQ state inspect kar sakta hoon','FIFO group/dedup aur idempotent dispatch boundaries choose kar sakta hoon','Queue/fan-out/stream/broker contract aur request costs compare kar sakta hoon'],
    homework:'<p><b>Optional approved AWS sandbox only; billable.</b> Confirm Region/quota/budget and current prices. Create owned topic, per-service queues, scoped resource/key/identity policies, processing DLQs and separate subscription delivery DLQ. Test matching/nonmatching body/attribute filters after propagation, provider-idempotent dispatch, slow/crashed consumer, poison retry/redrive and actual FIFO duplicate-after-delete behavior within5 minutes. Record message IDs, business IDs, receive counts, age, durable effects and delivery errors; no real customer events. Clean only owned subscriptions/topics/queues/DLQs, test outbox table, logs/alarms, roles and KMS resources with reviewed deletion schedule. Do not treat Moto behavior or an accepted publish as real AWS security/performance proof.</p>',
    cards:[{front:'Receive versus delete?',back:'Receive reserves visibility and returns a receipt; delete after the agreed durable processing contract using latest valid receipt. Visibility expiry can permit retry.'},{front:'One queue for all services?',back:'Workers in one queue compete. Independent email/invoice copies need separate queues, commonly behind SNS.'},{front:'SNS delivery permission?',back:'Producer Publish IAM plus destination queue SendMessage resource policy scoped to topic SourceArn; applicable KMS permissions also matter.'},{front:'Filter reads body?',back:'Default scope MessageAttributes. Explicit MessageBody for JSON payload fields; raw/envelope is a separate consumer-format choice.'},{front:'FIFO exactly-once business work?',back:'No automatic external atomicity. Per-group order plus five-minute producer dedup; consumer crash/ack ambiguity still needs stable identity/idempotent effects.'},{front:'Two DLQ contracts?',back:'SNS subscription DLQ for delivery failures; SQS source processing DLQ for retry-exhausted jobs already in the queue. Inspect before redrive.'},{front:'Conditional dedup flag enough?',back:'A flag before effect can lose work; flag after effect can duplicate. Recoverable durable intent plus idempotent/reconciled dispatch handles the boundary.'},{front:'Queue planner proves what?',back:'Declared expected retry/capacity/window arithmetic. No AWS throughput, latency, stochastic duplicates or exact DLQ timing measurement.'}]
  }]);
})();
